/**
 * Loads the campsite document [campsiteId] from Firestore and passes it to
 * [onResult], or null if it is missing or can't be read.
 */
fun loadCampsiteFromFirestore(campsiteId: String, onResult: (Campsite?) -> Unit) {
    if (campsiteId.isBlank()) return onResult(null)
    FirebaseFirestore.getInstance().collection("campsites").document(campsiteId).get()
        .addOnSuccessListener { doc -> onResult(runCatching { doc.toObject(Campsite::class.java) }.getOrNull()) }
        .addOnFailureListener {
            Log.e("Reviews", "Could not load campsite", it)
            onResult(null)
        }
}

/**
 * Shows every review of a campsite, newest first. Anyone except the campsite's
 * owner can post one review, and posting again edits it.
 *
 * @param navController used to go back to the campsite.
 * @param campsiteId ID of the campsite whose reviews are shown.
 * @param deviceId the current user's device ID.
 * @param authorName the current user's profile name, shown with their review.
 * @param reviewRepository where reviews are stored.
 * @param loadCampsite loads the campsite, to show its name and know who owns it.
 */
@Composable
fun CampsiteReviewsScreen(
    navController: NavController,
    campsiteId: String,
    deviceId: String,
    authorName: String,
    reviewRepository: ReviewRepository = remember { FirestoreReviewRepository() },
    loadCampsite: (String, (Campsite?) -> Unit) -> Unit = ::loadCampsiteFromFirestore,
) {
    var campsite by remember { mutableStateOf<Campsite?>(null) }
    var campsiteLoaded by remember { mutableStateOf(false) }
    var reviews by remember { mutableStateOf<List<Review>>(emptyList()) }
    var isLoading by remember { mutableStateOf(true) }
    var loadError by remember { mutableStateOf<String?>(null) }
    var reloadKey by remember { mutableStateOf(0) }

    var showDialog by remember { mutableStateOf(false) }
    // Text the user posted that hasn't saved yet, kept so a failed post isn't lost.
    var unsavedDraft by rememberSaveable { mutableStateOf<String?>(null) }
    var isSubmitting by remember { mutableStateOf(false) }
    var message by remember { mutableStateOf<String?>(null) }
    var submitError by remember { mutableStateOf<String?>(null) }

    LaunchedEffect(campsiteId, reloadKey) {
        isLoading = true
        loadError = null
        campsiteLoaded = false
        loadCampsite(campsiteId) {
            campsite = it
            campsiteLoaded = true
        }
        reviewRepository.getReviews(
            campsiteId,
            onSuccess = {
                reviews = it
                isLoading = false
            },
            onFailure = {
                Log.e("Reviews", "Could not load reviews", it)
                loadError = "Could not load reviews."
                isLoading = false
            },
        )
    }

    val myReview = reviews.firstOrNull { it.userId == deviceId }
    val canReview = campsite != null && ReviewPolicy.canReview(campsite!!.ownerId, deviceId)

    fun submit(text: String) {
        if (isSubmitting) return
        isSubmitting = true
        submitError = null
        message = null
        unsavedDraft = text
        val editing = myReview != null
        reviewRepository.submitReview(
            campsiteId,
            deviceId,
            authorName,
            text,
            onSuccess = { saved ->
                isSubmitting = false
                unsavedDraft = null
                reviews = ReviewPolicy.sortNewestFirst(reviews.filterNot { it.userId == deviceId } + saved)
                message = if (editing) "Your review was updated." else "Thanks! Your review was posted."
            },
            onFailure = {
                isSubmitting = false
                submitError = (it.message ?: "Could not post your review.") + " Your text was kept; tap the button to try again."
            },
        )
    }

    if (showDialog) {
        PostReviewDialog(
            initialText = unsavedDraft ?: myReview?.text,
            isEditing = myReview != null,
            onSubmit = { text ->
                showDialog = false
                submit(text)
            },
            onDismiss = { showDialog = false },
        )
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .statusBarsPadding()
            .navigationBarsPadding()
            .padding(16.dp),
    ) {
        Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.Absolute.Left) {
            Button(
                onClick = { navController.popBackStack() },
                shape = RectangleShape,
                modifier = Modifier.testTag("toBackButton"),
            ) {
                Text("Back")
            }
        }

        Spacer(modifier = Modifier.height(16.dp))
        Text("Reviews", fontSize = 40.sp, modifier = Modifier.testTag("reviewsHeader"))
        campsite?.let {
            Text(it.name, fontSize = 18.sp, modifier = Modifier.testTag("reviewsCampsiteName"))
        }
        Spacer(modifier = Modifier.height(16.dp))

        Box(modifier = Modifier.weight(1f).fillMaxWidth()) {
            when {
                campsiteLoaded && campsite == null && !isLoading -> Column(
                    modifier = Modifier.align(Alignment.Center),
                    horizontalAlignment = Alignment.CenterHorizontally,
                ) {
                    Text("Could not load this campsite.", fontSize = 18.sp, modifier = Modifier.testTag("campsiteMissingText"))
                    Spacer(modifier = Modifier.height(8.dp))
                    Button(
                        onClick = { reloadKey++ },
                        shape = RectangleShape,
                        modifier = Modifier.testTag("retryCampsiteButton"),
                    ) { Text("Retry") }
                }
                isLoading -> CircularProgressIndicator(modifier = Modifier.align(Alignment.Center))
                loadError != null -> Column(
                    modifier = Modifier.align(Alignment.Center),
                    horizontalAlignment = Alignment.CenterHorizontally,
                ) {
                    Text(loadError!!, color = MaterialTheme.colorScheme.error)
                    Spacer(modifier = Modifier.height(8.dp))
                    Button(
                        onClick = { reloadKey++ },
                        shape = RectangleShape,
                        modifier = Modifier.testTag("retryReviewsButton"),
                    ) { Text("Retry") }
                }
                reviews.isEmpty() -> Text(
                    if (canReview) "No reviews yet. Be the first to write one!" else "No reviews yet.",
                    fontSize = 18.sp,
                    modifier = Modifier.align(Alignment.Center).testTag("noReviewsText"),
                )
                else -> LazyColumn(
                    modifier = Modifier.fillMaxSize().testTag("reviewList"),
                    verticalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    items(reviews, key = { it.userId }) { review ->
                        ReviewCard(review, isMine = review.userId == deviceId)
                    }
                }
            }
        }

        Spacer(modifier = Modifier.height(8.dp))
        submitError?.let {
            Text(it, color = MaterialTheme.colorScheme.error, fontSize = 14.sp, modifier = Modifier.testTag("reviewErrorText"))
            Spacer(modifier = Modifier.height(4.dp))
        }
        message?.let {
            Text(it, fontSize = 14.sp, modifier = Modifier.testTag("reviewMessageText"))
            Spacer(modifier = Modifier.height(4.dp))
        }

        if (canReview) {
            Button(
                onClick = { showDialog = true },
                enabled = !isSubmitting && !isLoading && loadError == null,
                shape = RectangleShape,
                modifier = Modifier.fillMaxWidth().testTag("writeReviewButton"),
            ) {
                Text(
                    when {
                        isSubmitting -> "Posting review..."
                        myReview != null -> "Edit My Review"
                        else -> "Write a Review"
                    }
                )
            }
        }
    }
}

/** One review: who wrote it, when, and what they said. */
@Composable
private fun ReviewCard(review: Review, isMine: Boolean) {
    Card(modifier = Modifier.fillMaxWidth().testTag("reviewCard_${review.userId}")) {
        Column(modifier = Modifier.padding(horizontal = 16.dp, vertical = 12.dp)) {
            Text(
                ReviewPolicy.displayName(review) + if (isMine) " (you)" else "",
                fontWeight = FontWeight.Bold,
                fontSize = 16.sp,
            )
            Text(
                ReviewPolicy.displayDate(review.updatedAt),
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
            )
            Spacer(modifier = Modifier.height(6.dp))
            Text(review.text, fontSize = 16.sp)
        }
    }
}

